140	export async function listCommand(
141		listArgs: StrictYargsOptionsToInterface<typeof listYargs>,
142		config: Config
143	) {
144		if (isNonInteractiveOrCI()) {
145			const applications = await ApplicationsService.listApplications();
146			logger.json(applications);
147			return;
148		}
149	
150		await listCommandHandle(listArgs, config);
151	}
