34		}
35	
36		const raw = status.container_status ?? status.health;
37		switch (raw) {
38			case "placed":
39				return "provisioning";
40			case "running":
41			case "failed":
42			case "stopping":
43			case "stopped":
44			case "unhealthy":
45				return raw;
46			default:
47				return "unknown";
48		}
49	}
