51	function colorState(state: ContainerState): string {
52		switch (state) {
53			case "running":
54				return green(state);
55			case "failed":
56			case "unhealthy":
57			case "stopped":
58			case "stopping":
59				return red(state);
60			default:
61				return state;
62		}
63	}
