/**
 * Derive an application's state from its health instance counters, using a
 * strict priority order:
 *   - failed > 0                       -> degraded
 *   - starting > 0 or scheduling > 0   -> provisioning
 *   - active > 0                       -> active
 *   - otherwise                        -> ready
 */
function deriveApplicationState(app: DashApplication): ApplicationState {
	const instances = app.health?.instances;
	if (instances) {
		if (instances.failed > 0) {
			return "degraded";
		}
		if (instances.starting > 0 || instances.scheduling > 0) {
			return "provisioning";
		}
		if (instances.active > 0) {
			return "active";
		}
	}
	return "ready";
}

function colorApplicationState(state: ApplicationState): string {
	switch (state) {
		case "active":
			return green(state);
		case "degraded":
			return red(state);
		default:
			return state;
	}
}

