type ContainerState =
	| "provisioning"
	| "running"
	| "failed"
	| "stopping"
	| "stopped"
	| "unhealthy"
	| "inactive"
	| "unknown";

function deriveInstanceState(
	instance: DashApplicationInstance
): ContainerState {
	const status = instance.current_placement?.status;
	if (!status) {
		return "unknown";
	}

	const raw = status.container_status ?? status.health;
	switch (raw) {
		case "placed":
			return "provisioning";
		case "running":
		case "failed":
		case "stopping":
		case "stopped":
		case "unhealthy":
			return raw;
		default:
			return "unknown";
	}
}

function colorState(state: ContainerState): string {
	switch (state) {
		case "running":
			return green(state);
		case "failed":
		case "unhealthy":
		case "stopped":
		case "stopping":
			return red(state);
		default:
			return state;
	}
}

